#!/usr/bin/env dotnet
// friday13.cs — Friday the 13th in the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep going (but it will be found)
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (true)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            break;
        }
        date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th (proleptic Gregorian): {earliest:yyyy-MM-dd}");
Console.WriteLine($"  Day of week check: {earliest!.Value.DayOfWeek}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year Gregorian cycle (the calendar repeats every 400 years)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();

// Bonus: distribution of the 13th by day of week over 400 years
var dayCounts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        dayCounts[(int)d.DayOfWeek]++;
    }
}

Console.WriteLine("Distribution of the 13th by day of week (400-year cycle):");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
{
    Console.WriteLine($"  {dow,-10}: {dayCounts[(int)dow],4}");
}

